float vrchPyramidSdf(vec3 p) {
  p.y += 0.12;
  float body = max(max(abs(p.x), abs(p.z)) + p.y * 0.72 - 0.48, -p.y - 0.52);
  return max(body, p.y - 0.58);
}
vec3 vrchPyramidNormal(vec3 p) {
  vec2 e = vec2(0.0015, 0.0);
  return normalize(vec3(
    vrchPyramidSdf(p + e.xyy) - vrchPyramidSdf(p - e.xyy),
    vrchPyramidSdf(p + e.yxy) - vrchPyramidSdf(p - e.yxy),
    vrchPyramidSdf(p + e.yyx) - vrchPyramidSdf(p - e.yyx)
  ));
}
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  float low = vrchReadSignal(0);
  float beat = vrchReadSignal(1);
  float angle = iTime * uParam_rotation_speed;
  mat2 rotation = mat2(cos(angle), -sin(angle), sin(angle), cos(angle));
  vec3 rayOrigin = vec3(0.0, 0.05, uParam_camera_distance);
  vec3 rayDirection = normalize(vec3(p, -1.65));
  float distanceTravelled = 0.0;
  float hitDistance = 1.0;
  vec3 objectPoint = vec3(0.0);
  for (int i = 0; i < 48; i++) {
    vec3 worldPoint = rayOrigin + rayDirection * distanceTravelled;
    objectPoint = worldPoint;
    objectPoint.xz = rotation * objectPoint.xz;
    objectPoint /= uParam_scale + low * 0.08;
    hitDistance = vrchPyramidSdf(objectPoint) * (uParam_scale + low * 0.08);
    distanceTravelled += hitDistance;
  }
  vec3 background = mix(vec3(0.008, 0.012, 0.028), vec3(0.035, 0.055, 0.11), 1.0 - uv.y);
  float hit = 1.0 - step(0.008, abs(hitDistance));
  vec3 normal = vrchPyramidNormal(objectPoint);
  vec3 lightDirection = normalize(vec3(-0.45, 0.7, 0.55));
  float diffuse = 0.18 + max(0.0, dot(normal, lightDirection)) * uParam_light;
  float rim = pow(1.0 - max(0.0, dot(normal, -rayDirection)), 3.0);
  vec3 surface = uParam_surface_color.rgb * diffuse + uParam_glow * (rim + beat * 0.25) * vec3(0.2, 0.75, 1.0);
  float halo = exp(-9.0 * abs(hitDistance)) * uParam_glow * 0.08;
  vec3 color = mix(background + halo * vec3(0.12, 0.5, 1.0), surface, hit);
  fragColor = vec4(color, 1.0);
}
